// The small life of the realm, drawn from the books: what the smallfolk, septons, maesters, sellswords and
// lords of Westeros and Essos get up to while the great game is played. The engine (shared/happenings.js)
// picks from these every turn, fills in the names and places, and applies their small effects.
//
//  H(id, where, importance, type, title, text, { when, fx, w, cd })
//   where: 'any' | 'r:north|vale' (a region) | 'h:manderly|stark' (holdings) | 'c:walder_frey' (where a person is)
//   when:  war · peace · winter · cold · warm · summer · unrest · calm · rich · poor · coast · town · lord · oldlord ·
//          younglord · wildlings · dead · mine (the player's realm) · notmine · alive:id+id · flag:x · noflag:x
//   fx:    pro (prosperity ±), unr (unrest ±), rel (with the house's rival ±), relf (with its friend ±), note (remembered)
//   w: weight (default 1) · cd: turns before it can come again (default 6)
//   text slots: {place} {house} {lord} {lordshort} {region} {knight} {smallfolk} {smallfolk2} {goods} {sea} {rival}
//               {friend} {season} {n:10-200}.  "A || B" picks one of the variants.
//
// Canon is respected: nothing here states as fact what happens after 298 AC; later things appear only as rumour.

const H = (id, where, imp, type, t, x, o = {}) => ({ id, where, imp, type, t, x, ...o });

